const op = msg.payload;
const size = bytes => {
    const units = ["B", "KB", "MB", "GB", "TB"];
    let i = 0;
    while (bytes >= 1024 && i < units.length - 1) { bytes /= 1024; i++; }
    return `${bytes.toFixed(i ? 1 : 0)} ${units[i]}`;
};

const what = { backup: "Backup", check: "Repository check", prune: "Prune" }[msg.operationType];
const lines = [
    msg.status === "STATUS_WARNING"
        ? `⚠️ **${what} finished with warnings**`
        : `❌ **${what} failed**`,
    ""
];
// Repository tasks such as check and prune have no plan
if (op.planId && op.planId !== "_system_") lines.push(`- Plan: \`${op.planId}\``);
lines.push(`- Repository: \`${op.repoId}\``);
if (op.snapshotId) {
    lines.push(`- Snapshot: \`${op.snapshotId.slice(0, 8)}\``);
    const s = op.operationBackup && op.operationBackup.lastStatus && op.operationBackup.lastStatus.summary;
    if (s) {
        const n = value => Number(value || 0);
        lines.push(
            `- Files: ${n(s.filesNew)} new, ${n(s.filesChanged)} changed, ${n(s.filesUnmodified)} unmodified`,
            `- Data added: ${size(n(s.dataAdded))} (${size(n(s.totalBytesProcessed))} processed)`,
            `- Duration: ${Math.round(n(s.totalDuration))}s`
        );
    }
}
if (op.displayMessage) lines.push("", "```", op.displayMessage.trim(), "```");

msg.payload = lines.join("\n");
// The Send Message node posts to msg.topic when it has no room set
delete msg.topic;
return msg;
